function setTab(tab){activeTab=tab;const panels={library:['libraryView'],notes:['notesHome'],favorites:['favoritesHome'],profile:['profileHome']};Object.values(panels).flat().forEach(id=>$(id).classList.add('hidden'));(panels[tab]||panels.library).forEach(id=>$(id).classList.remove('hidden'));document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='notes')drawGlobalNotes();if(tab==='favorites')drawFavorites();if(tab==='profile'){renderStats();renderStorage()}window.scrollTo(0,0)}
function drawGlobalNotes(){const list=$('globalNotesList');list.replaceChildren();$('wordTools').classList.toggle('hidden',globalNoteMode!=='words');if(globalNoteMode==='words'){drawWordBook(list);return}const all=[];for(const b of books){for(const n of b.annotations||[])all.push({book:b,n,kind:'note'});for(const n of b.words||[])all.push({book:b,n,kind:'word'})}all.sort((a,b)=>(b.n.at||0)-(a.n.at||0));const filtered=all.filter(x=>globalNoteMode==='all'||(globalNoteMode==='words'?x.kind==='word':globalNoteMode==='thoughts'?x.kind==='note'&&!!x.n.thought:x.kind==='note'));if(!filtered.length){list.innerHTML='<p class="panel-empty">这里暂时没有内容。阅读中划线、写想法或收藏生词后会显示在这里。</p>';return}for(const x of filtered){if(x.kind==='word'){list.append(wordBookRow(x.book,x.n));continue}const card=document.createElement('article');card.className='journal-entry';const label=document.createElement('div');label.className='journal-label';label.textContent=x.book.title+' · '+(x.kind==='word'?'生词':x.n.thought?'划线与想法':'划线');card.append(label);const q=document.createElement('blockquote');q.textContent=x.kind==='word'?x.n.word:x.n.quote||'';card.append(q);const p=document.createElement('p');p.textContent=x.kind==='word'?x.n.meaning||'尚无释义':x.n.thought||'';if(p.textContent)card.append(p);if(x.kind==='word'){const status=document.createElement('button');status.className='mastery-toggle';status.textContent=x.n.mastered?'✓ 已掌握 · 点击取消':'○ 标记已掌握';status.onclick=async()=>{x.n.mastered=!x.n.mastered;await put(x.book);drawGlobalNotes()};card.append(status)}const foot=document.createElement('div');foot.className='journal-foot';const date=document.createElement('span');date.textContent=new Date(x.n.at||Date.now()).toLocaleDateString();foot.append(date);const button=document.createElement('button');button.textContent=x.kind==='note'?'回到原书':'打开书籍';button.onclick=async()=>{await openBook(x.book.id);if(x.kind==='note'&&epub)renderChapter(x.n.chapter||0,0)};foot.append(button);card.append(foot);list.append(card)}}
function exportAllNotes(){let md='# 页间 · 全部笔记与生词\n\n';for(const b of books){if(!(b.annotations||[]).length&&!(b.words||[]).length)continue;md+='## '+b.title+'\n\n';for(const n of b.annotations||[])md+='> '+(n.quote||'').replaceAll('\n','\n> ')+'\n\n'+(n.thought||'')+'\n\n';for(const n of b.words||[])md+='- **'+n.word+'**：'+(n.meaning||'')+'\n';md+='\n'}downloadFile('quietleaf-notes.md',new Blob([md],{type:'text/markdown;charset=utf-8'}))}
function downloadFile(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
const FAV_KEY='quietleaf-favorites-v3';function favorites(){try{return JSON.parse(localStorage.getItem(FAV_KEY)||'[]')}catch{return []}}function saveFavorites(f){localStorage.setItem(FAV_KEY,JSON.stringify(f))}
function drawFavorites(){const list=$('favoriteList');list.replaceChildren();const f=favorites();$('favoriteForm').classList.toggle('hidden',f.length>0&&!favFormOpen);$('favAdd').classList.toggle('hidden',!f.length);$('favAdd').textContent=favFormOpen?'×':'＋';if(!f.length){list.innerHTML='<p class="panel-empty">还没有收藏的网站。粘贴一个链接，即可随时从这里打开。</p>';return}for(const item of f){const row=document.createElement('div');row.className='favorite-item';const info=document.createElement('div');info.className='favorite-info';const name=document.createElement('strong');name.textContent=item.title;const domain=document.createElement('span');domain.textContent=new URL(item.url).hostname;info.append(name,domain);const open=document.createElement('button');open.textContent='打开 ↗';open.onclick=()=>window.open(item.url,'_blank','noopener,noreferrer');const remove=document.createElement('button');remove.textContent='删除';remove.setAttribute('aria-label','删除 '+item.title);remove.onclick=()=>{saveFavorites(favorites().filter(x=>x.id!==item.id));drawFavorites()};row.append(info,open,remove);list.append(row)}}
function logReading(){if(!current||document.hidden||!epub&&!pdfUrl)return;const today=new Date().toLocaleDateString('en-CA');const days=JSON.parse(localStorage.getItem('quietleaf-read-days')||'{}');days[today]=true;localStorage.setItem('quietleaf-read-days',JSON.stringify(days));const seconds=Number(localStorage.getItem('quietleaf-read-seconds')||0);localStorage.setItem('quietleaf-read-seconds',String(seconds+15))}
