function renderStats(){const allWords=books.reduce((n,b)=>n+(b.words||[]).length,0),allNotes=books.reduce((n,b)=>n+(b.annotations||[]).length,0);$('statBooks').textContent=books.length;$('statFinished').textContent=books.filter(b=>(b.progress||0)>=.995).length;$('statMinutes').textContent=Math.floor(Number(localStorage.getItem('quietleaf-read-seconds')||0)/60);$('statWords').textContent=allWords;$('statNotes').textContent=allNotes;$('statDays').textContent=Object.keys(JSON.parse(localStorage.getItem('quietleaf-read-days')||'{}')).length;$('vocabLevel').value=prefs.vocabLevel;$('vocabMax').value=prefs.vocabMax;$('hideMastered').checked=prefs.hideMastered}
let wordsTimer=null,lookupVersion=0;
const STOPWORDS=new Set('the and for are was were has have had with from that this those these not but can did does what when where which their there about into upon while then than them they she her his him its you your our out one two three all any each only very also just some more most like even over under after before would could should will shall said says been being make made many much such other another people first last time little right still here away well down back through because between without across against enough every never always really itself himself herself myself yourself ourselves themselves through thought though until since whose whoever whom whomsoever often perhaps quite rather almost already again why how who whose whose'.split(' '));
const LOCAL_WORDS={serene:'平静的；安宁的',resilient:'有韧性的；能恢复的',curiosity:'好奇心',journey:'旅程',despite:'尽管',wonder:'惊奇；想知道',suddenly:'突然地',whisper:'低语',mysterious:'神秘的',magnificent:'壮丽的',adventure:'冒险',ponder:'认真思考',pondered:'认真思考',extraordinary:'非凡的',inevitable:'不可避免的',melancholy:'忧郁',wisdom:'智慧',beneath:'在……下面',beyond:'在……之外',gentle:'温柔的',glimpse:'一瞥',solitude:'独处',tranquil:'宁静的',profound:'深刻的',serendipity:'意外发现美好事物的机缘',pilgrim:'朝圣者',civilization:'文明',unusually:'不寻常地',delicate:'精致的；脆弱的',frequently:'频繁地',reluctant:'不情愿的',obscure:'模糊的；鲜为人知的',vivid:'生动的',trembling:'颤抖的',shimmering:'闪烁的',delight:'愉悦',peculiar:'奇特的',vast:'广阔的',silent:'安静的',ancient:'古老的',remarkable:'非凡的',gradually:'逐渐地',distant:'遥远的'};
function schedulePageWords(){clearTimeout(wordsTimer);wordsTimer=setTimeout(refreshPageWords,330)}
function extractWords(text){const count=new Map();text=String(text||'').replace(/[\u00AD\u200B-\u200D\u2060\uFEFF]/g,'');const add=word=>{if(word.length<3||STOPWORDS.has(word))return;count.set(word,(count.get(word)||0)+1)};for(const raw of text.match(/[a-zA-Z]+(?:['’-][a-zA-Z]+)*/g)||[]){const word=raw.toLowerCase();if(/['’]/.test(word))continue;if(word.includes('-')&&!(QLDict.ready()&&QLDict.get(word))){word.split('-').forEach(add);continue}add(word)}const known=new Set((current?.words||[]).filter(w=>w.mastered).map(w=>w.word.toLowerCase()));const max=isLandscape()?400:prefs.vocabMax==='all'?30:Number(prefs.vocabMax)||8;if(QLDict.ready()){const min=prefs.vocabLevel==='basic'?3:prefs.vocabLevel==='advanced'?5:4;const listBit=VOCAB_LISTS[prefs.vocabLevel],skip=prefs.vocabLevel==='ielts-hard'?7:3;const seen=new Map();for(const [word,n] of count){const e=QLDict.get(word);if(!e)continue;if(listBit&&e.bits!=null){if(!(e.bits&listBit)||(e.bits&skip))continue}else if(e.level<min)continue;if(prefs.hideMastered&&(known.has(word)||known.has(e.lemma)))continue;const prev=seen.get(e.lemma);if(prev){prev.frequency+=n;continue}seen.set(e.lemma,{word:e.lemma,frequency:n,meaning:e.meaning,level:e.level,phonetic:e.phonetic})}return [...seen.values()].slice(0,max)}let list=[...count].filter(([word])=>word.length>=5).map(([word,n])=>({word,frequency:n,meaning:LOCAL_WORDS[word]||'点击查看释义'}));if(prefs.hideMastered)list=list.filter(x=>!known.has(x.word));const limit=prefs.vocabLevel==='basic'?5:prefs.vocabLevel==='advanced'?9:7;list=list.filter(x=>x.word.length>=limit||LOCAL_WORDS[x.word]);list.sort((a,b)=>(LOCAL_WORDS[b.word]?1:0)-(LOCAL_WORDS[a.word]?1:0)||b.word.length-a.word.length||a.word.localeCompare(b.word));return list.slice(0,max)}
function refreshPageWords(){if(!epub||!current)return;const text=pageText();pageCandidates=extractWords(text);if(dockMode!=='detail')dockMode='auto';drawDock()}
