function sayWord(w){w=(w||'').trim();if(!w)return;if(prefs.ttsEngine==='google'){say(w);return}if(!('speechSynthesis'in window)){toast('当前浏览器不支持语音合成');return}try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(w);u.lang='en-US';u.rate=Math.max(.6,Math.min(1.4,prefs.speechRate||1));const v=speechSynthesis.getVoices().find(x=>/^en[-_]US/i.test(x.lang))||speechSynthesis.getVoices().find(x=>/^en/i.test(x.lang));if(v)u.voice=v;speechSynthesis.speak(u)}catch{}}
function savedEntry(book,word){const w=(word||'').toLowerCase();return (book?.words||[]).find(x=>x.word.toLowerCase()===w)}
function isSaved(word){if(!current)return false;const e=QLDict.ready()?QLDict.get(word):null;return !!(savedEntry(current,word)||(e&&savedEntry(current,e.lemma)))}
