async function makeBackup(){const payload={app:'QuietLeaf',version:3,created:new Date().toISOString(),prefs:{...prefs,ttsToken:''},favorites:favorites(),books:await Promise.all(books.map(async b=>{const data=new Uint8Array(await b.file.arrayBuffer());let binary='';for(let i=0;i<data.length;i+=8192)binary+=String.fromCharCode(...data.slice(i,i+8192));return {...b,file:undefined,blobBase64:btoa(binary)}})),readSeconds:Number(localStorage.getItem('quietleaf-read-seconds')||0),readDays:JSON.parse(localStorage.getItem('quietleaf-read-days')||'{}')};const name='quietleaf-backup-'+new Date().toISOString().slice(0,10)+'.json';return {name,blob:new Blob([JSON.stringify(payload)],{type:'application/json'})}}
function kvDb(){return new Promise((res,rej)=>{const r=indexedDB.open('quietleaf-settings',1);r.onupgradeneeded=()=>r.result.createObjectStore('kv');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function kv(mode,key,val){const d=await kvDb();try{return await new Promise((res,rej)=>{const tx=d.transaction('kv',mode),st=tx.objectStore('kv'),q=mode==='readonly'?st.get(key):val===undefined?st.delete(key):st.put(val,key);tx.oncomplete=()=>res(q.result);tx.onerror=()=>rej(tx.error)})}finally{d.close()}}
