// mode: 'silent' (folder only, no prompts) | 'share' (folder, else share sheet) | 'download' (folder, else download)
async function deliverBackup(mode){let dir=null;try{dir=canPickDir()?await kv('readonly','backupDir'):null}catch{}
 if(dir){let perm='denied';try{perm=await dir.queryPermission({mode:'readwrite'});if(perm!=='granted'&&mode!=='silent')perm=await dir.requestPermission({mode:'readwrite'})}catch{}if(perm==='granted'){try{await writeToDir(dir,preparedBackup||await makeBackup());markBackedUp();toast('已备份到文件夹「'+dir.name+'」');return true}catch(e){if(mode==='silent')return false;toast('写入文件夹失败：'+e.message)}}}
 if(mode==='silent')return false;const b=preparedBackup||await prepareBackup();const file=new File([b.blob],b.name,{type:'application/json'});
 if(mode==='share'&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'页间数据备份'});markBackedUp();toast('备份已保存');return true}catch(e){if(e.name==='AbortError')return false}}
 downloadFile(b.name,b.blob);markBackedUp();toast('已生成备份文件，请保存到「文件」App');return true}
function backupDue(){const c=backupCfg();if(!c.on||!books.length)return false;const now=Date.now(),snooze=Number(localStorage.getItem('quietleaf-backup-snooze')||0);if(now<snooze)return false;const last=lastBackup()||Number(localStorage.getItem('quietleaf-first-use')||now);return now-last>=c.days*864e5}
async function checkBackupDue(){if(!backupDue()){$('backupBanner').classList.add('hidden');return}if(await deliverBackup('silent'))return;const last=lastBackup();$('backupBannerText').textContent=last?'已 '+Math.floor((Date.now()-last)/864e5)+' 天没有备份':'还没有备份过书籍和笔记';$('backupBanner').classList.remove('hidden');$('backupNow').disabled=true;$('backupNow').textContent='准备中…';try{await prepareBackup()}catch{}$('backupNow').disabled=false;$('backupNow').textContent='立即备份'}
async function renderBackupSettings(){const c=backupCfg();$('autoBackupOn').checked=c.on;$('autoBackupDays').value=c.days;$('autoBackupDays').disabled=!c.on;let dir=null;try{dir=canPickDir()?await kv('readonly','backupDir'):null}catch{}
 $('pickBackupDir').classList.toggle('hidden',!canPickDir());$('clearBackupDir').classList.toggle('hidden',!dir);$('backupDest').textContent=dir?'文件夹「'+dir.name+'」':canPickDir()?'未选择（到期时提醒你下载）':'「文件」App（到期时提醒）';
 const last=lastBackup();$('backupHint').textContent=(c.on?'下次备份：'+(last?new Date(last+c.days*864e5).toLocaleDateString():'导入书籍后 '+c.days+' 天')+'。':'定期备份已关闭。')+(canPickDir()?(dir?' 到期后打开页面会自动写入该文件夹。':''):' iPhone 不允许网页指定文件夹或在后台写文件：到期打开 App 时，书架顶部会提醒，点「立即备份」→ 存储到「文件」并选文件夹，iOS 会记住上次的位置。')}
function initAutoBackup(){try{if(!localStorage.getItem('quietleaf-first-use'))localStorage.setItem('quietleaf-first-use',String(Date.now()))}catch{}
 $('autoBackupOn').onchange=e=>{saveBackupCfg({...backupCfg(),on:e.target.checked});renderBackupSettings();renderStorage();checkBackupDue()};
 $('autoBackupDays').onchange=e=>{const d=Math.max(1,Math.min(365,Math.round(Number(e.target.value)||7)));saveBackupCfg({...backupCfg(),days:d});renderBackupSettings();renderStorage();checkBackupDue()};
 $('pickBackupDir').onclick=async()=>{try{const dir=await window.showDirectoryPicker({id:'quietleaf-backup',mode:'readwrite'});await kv('readwrite','backupDir',dir);toast('之后会自动备份到「'+dir.name+'」');renderBackupSettings()}catch(e){if(e.name!=='AbortError')toast('无法使用该文件夹：'+e.message)}};
 $('clearBackupDir').onclick=async()=>{await kv('readwrite','backupDir');renderBackupSettings()};
 $('backupNow').onclick=()=>deliverBackup('share');$('backupLater').onclick=()=>{try{localStorage.setItem('quietleaf-backup-snooze',String(Date.now()+864e5))}catch{}$('backupBanner').classList.add('hidden')};
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&activeTab==='library'&&!current)checkBackupDue()});renderBackupSettings();setTimeout(checkBackupDue,1500)}
// ---- highlights: per-text-node marks, contextual toolbar, edit menu
var editingHighlight=null,noteEditTarget=null;
function wrapRange(r,a){const root=r.commonAncestorContainer.nodeType===3?r.commonAncestorContainer.parentNode:r.commonAncestorContainer;const nodes=[];const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(r.intersectsNode(n))nodes.push(n)}
 for(let t of nodes){const len=t.textContent.length;let st=t===r.startContainer?r.startOffset:0,en=t===r.endContainer?r.endOffset:len;if(en<=st)continue;if(!t.textContent.slice(st,en).trim()&&/\n/.test(t.textContent))continue;if(en<len)t.splitText(en);if(st>0)t=t.splitText(st);const m=document.createElement('mark');m.className='highlight-mark';m.dataset.noteColor=a.color||'yellow';m.dataset.noteId=a.id;if(a.thought)m.dataset.hasThought='1';t.parentNode.insertBefore(m,t);m.appendChild(t)}}
function clearMarks(){const c=$('chapterContent');c.querySelectorAll('mark.highlight-mark').forEach(m=>m.replaceWith(...m.childNodes));c.normalize()}
function refreshMarks(){clearMarks();restoreMarks()}
function showSelBar(rectSource,mode,color){const bar=$('selectionBar');bar.dataset.mode=mode;$('deleteHighlight').classList.toggle('hidden',mode!=='edit');$('lookupSelection').classList.toggle('hidden',mode==='edit');$('noteSelection').textContent=mode==='edit'?'想法':'写想法';
 bar.querySelectorAll('[data-hl]').forEach(b=>b.classList.toggle('current',mode==='edit'?b.dataset.hl===color:b.dataset.hl===(prefs.hlColor||'yellow')));
 bar.classList.remove('hidden');bar.style.visibility='hidden';placeSelBar(bar,rectSource,mode==='new');bar.style.visibility=''}
function placeSelBar(bar,rectSource,nativeMenu){const rects=[...(rectSource.getClientRects?.()||[])].filter(r=>r.width||r.height);const first=rects[0]||rectSource.getBoundingClientRect(),last=rects[rects.length-1]||first;const bw=bar.offsetWidth,bh=bar.offsetHeight,vw=innerWidth,vh=innerHeight;
 const safeTop=parseFloat(getComputedStyle($('readerView')).paddingTop)||0;const card=$('wordCard'),cardTop=card&&!isLandscape()&&getComputedStyle(card).display!=='none'?card.getBoundingClientRect().top:vh;const floor=Math.min(vh,cardTop)-8;
 const NATIVE=58,HANDLE=18,GAP=10;let top;
 if(nativeMenu){const nativeAbove=first.top-NATIVE>=safeTop+4;
  if(nativeAbove){top=last.bottom+HANDLE;if(top+bh>floor){const up=first.top-NATIVE-GAP-bh;top=up>=safeTop+4?up:floor-bh}}
  else{top=last.bottom+NATIVE+GAP;if(top+bh>floor)top=floor-bh}}
 else{top=last.bottom+GAP;if(top+bh>floor){const up=first.top-GAP-bh;top=up>=safeTop+4?up:floor-bh}}
 top=Math.max(safeTop+4,top);let left=(Math.min(first.left,last.left)+Math.max(first.right,last.right))/2-bw/2;left=Math.max(8,Math.min(vw-bw-8,left));bar.style.left=left+'px';bar.style.top=top+'px'}
function openHighlightMenu(id){const a=allNotes().find(x=>x.id===id);if(!a)return;window.getSelection()?.removeAllRanges();pendingSelection=null;editingHighlight=id;const marks=[...$('chapterContent').querySelectorAll('mark.highlight-mark[data-note-id="'+CSS.escape(id)+'"]')];if(!marks.length)return;const r=document.createRange();r.setStartBefore(marks[0]);r.setEndAfter(marks[marks.length-1]);showSelBar(r,'edit',a.color||'yellow')}
function onColorPick(color){if(editingHighlight){const a=allNotes().find(x=>x.id===editingHighlight);if(a){a.color=color;prefs.hlColor=color;applyPrefs();saveSoon();$('chapterContent').querySelectorAll('mark.highlight-mark[data-note-id="'+CSS.escape(a.id)+'"]').forEach(m=>m.dataset.noteColor=color)}hideSelection();return}saveHighlight('',color)}
async function copySelectionText(){const text=editingHighlight?allNotes().find(x=>x.id===editingHighlight)?.quote:pendingSelection?.text;if(!text)return;let ok=false;try{await navigator.clipboard.writeText(text);ok=true}catch{try{const t=document.createElement('textarea');t.value=text;t.setAttribute('readonly','');t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();ok=document.execCommand('copy');t.remove()}catch{}}hideSelection();toast(ok?'已复制':'复制失败，请长按文字用系统菜单复制')}
function deleteEditingHighlight(){const id=editingHighlight;if(!id||!current)return;current.annotations=allNotes().filter(x=>x.id!==id);hideSelection();refreshMarks();saveSoon();toast('已删除划线')}
function openNoteEditorFor(id){const a=allNotes().find(x=>x.id===id);if(!a)return;noteEditTarget=id;$('noteQuote').textContent=a.quote;$('noteText').value=a.thought||'';$('selectionBar').classList.add('hidden');editingHighlight=null;openSheet('noteEditorSheet')}
